const EXPECTED_SOURCE_PATHS = Object.freeze([
  "packages/core/src/ir/semantics/semantic-clone.ts",
  "packages/core/src/ir/semantics/semantic-env.ts"
]);
const EXPECTED_COMPILED_PATHS = Object.freeze([
  "ir/semantics/semantic-clone.js",
  "ir/semantics/semantic-env.js"
]);

function exactRows(rows, expectedPaths) {
  return (
    Array.isArray(rows) &&
    rows.length === expectedPaths.length &&
    rows.every((row, index) =>
      row?.claim === CLAIM &&
      row.path === expectedPaths[index] &&
      /^[0-9a-f]{64}$/u.test(row.currentDigest) &&
      /^[0-9a-f]{64}$/u.test(row.expectedDigest) &&
      Array.isArray(row.replacements) &&
      row.replacements.length > 0
    )
  );
}

export function executionContextHardeningFormatCompiledReconstruction(path) {
  return POST_EXECUTION_CONTEXT_HARDENING_FORMAT_COMPILED_RECONSTRUCTIONS.find((row) => row.path === path);
}

export function validateExecutionContextHardeningFormatHistoricalTransition({
  transition = EXECUTION_CONTEXT_HARDENING_FORMAT_HISTORICAL_TRANSITION,
  sourceReconstructions = POST_EXECUTION_CONTEXT_HARDENING_FORMAT_SOURCE_RECONSTRUCTIONS,
  compiledReconstructions = POST_EXECUTION_CONTEXT_HARDENING_FORMAT_COMPILED_RECONSTRUCTIONS,
} = {}) {
  if (
    transition?.claim !== CLAIM ||
    transition.predecessorCommit !== PREDECESSOR_COMMIT ||
    transition.successorCommit !== SUCCESSOR_COMMIT ||
    JSON.stringify(transition.sourceManifest) !== '{"count":2,"digest":"2b3750a10ccbc51433fc5e5db01b5b9cd3896923957fc6261ad46410bae3f3d1"}' ||
    JSON.stringify(transition.compiledManifest) !== '{"count":2,"digest":"dbc5059e4d4a921f7152977ff4aae1a6f3f5832f39841aea54a1117d04076b7d"}' ||
    JSON.stringify(transition.sourceEndpoints) !== '{"predecessor":"4b71f32a7e06e2d140a2120b5ba892fe6615b87f3512eca62612da9eb661d0d3","successor":"5d3615e0c41460108644452cdf7513abe6b3b5dcb2939fe8ce9278713cfbcf4e"}' ||
    JSON.stringify(transition.compiledEndpoints) !== '{"predecessor":"2915aea7da571773e06d6f682ed9890a7761d0eb78dab8de9d4e7f480d196671","successor":"f776c6a72b0d3b303d68977bcda0d7ce724d9e44211b72fe0fe01c0b6eb5eebb"}' ||
    JSON.stringify(transition.compiledInventory?.predecessor) !== '{"count":317,"digest":"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67"}' ||
    JSON.stringify(transition.compiledInventory?.successor) !== '{"count":317,"digest":"34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67"}' ||
    !exactRows(sourceReconstructions, EXPECTED_SOURCE_PATHS) ||
    !exactRows(compiledReconstructions, EXPECTED_COMPILED_PATHS)
  ) {
    throw new TypeError('execution-context hardening format historical transition immutable identity changed');
  }
  return true;
}
